const BASE={"adjusted-body-weight":"Adjusted Body Weight is a calculated reference that combines actual weight with a reference weight; the exact method should match the clinical or nutrition protocol being used.","obesity-class":"Adult obesity classification is commonly based on BMI, but BMI is a screening measure and does not by itself diagnose health risk or body composition.","target-weight":"A target weight is a planning value. It should be interpreted with health, body composition, goals, and sustainability rather than treated as one universally correct number.","target-weight-bmi":"A BMI-based target weight is a mathematical estimate derived from the selected BMI and height. BMI is a screening measure, not a complete health assessment.","weight-loss-percentage":"Weight-loss percentage describes the amount of scale weight lost relative to starting weight. It does not identify how much fat, lean tissue, or water changed.","weight-gain-percentage":"Weight-gain percentage describes the amount of scale weight gained relative to starting weight. It does not determine whether the gain is fat, muscle, water, or another component.","weight-change":"Weight change is the difference between ending and starting weight. Short-term changes can reflect water, glycogen, food contents, fat, lean tissue, or measurement conditions.","weight-loss-timeline":"A weight-loss timeline estimates duration from the amount of weight to lose and an assumed average rate. Real progress is rarely perfectly linear.","goal-weight-date":"A goal-weight date is a mathematical projection based on planned weight change and an assumed average rate. It should be treated as an estimate rather than a deadline.","weekly-weight-loss":"Weekly weight loss is an average rate calculated over a period. Individual weeks can vary because of water balance, glycogen, food contents, activity, and other factors.","calories-to-lose-1-kg":"Calorie estimates for losing 1 kg are approximations. Traditional energy-equivalent rules can help with simple planning, but real-world weight change is dynamic.","calories-to-gain-1-kg":"Calorie estimates for gaining 1 kg are approximations. The energy cost varies with the composition of the gain and changes in energy expenditure."};const FORMULA_ANS={"weight-loss-percentage":"Use (starting weight − current weight) ÷ starting weight × 100. Keep units consistent; the result describes scale-weight change.","weight-gain-percentage":"Use (current weight − starting weight) ÷ starting weight × 100. Keep units consistent; the result describes total scale-weight change.","weight-change":"Subtract starting weight from ending weight. For percentage change, divide the difference by starting weight and multiply by 100.","weight-loss-timeline":"A simple estimate is weeks = weight to lose ÷ assumed average weekly loss. The result is a projection because the actual rate can change.","goal-weight-date":"Calculate the planned weight change, divide it by the assumed average weekly change, and add the resulting weeks to the selected start date.","weekly-weight-loss":"Average weekly loss = total weight lost ÷ number of weeks. Use consistent measurements and evaluate the trend rather than one reading.","target-weight-bmi":"For an adult BMI-based target, target weight in kilograms = target BMI × height in metres squared. BMI remains a screening measure.","calories-to-lose-1-kg":"A traditional planning approximation uses about 7,700 kcal per kilogram of fat-equivalent energy, but actual weight loss is dynamic and does not follow a fixed conversion indefinitely.","calories-to-gain-1-kg":"A simple calorie-surplus estimate can support planning, but the energy required to gain 1 kg varies with whether the gain is fat, lean tissue, water, or a mixture.","adjusted-body-weight":"Use the specific ABW equation selected by the applicable protocol, commonly combining ideal body weight with a fraction of excess weight. Correction factors vary by protocol.","target-weight":"A target weight can be estimated from a selected BMI range, body-fat goal, or other method. The appropriate method depends on the purpose and individual context.","obesity-class":"For adults, BMI is calculated as weight in kilograms divided by height in metres squared, then compared with the applicable adult classification thresholds."};const sensitive=/\b(safe|risk|medical|clinical|doctor|guideline|pregnan|breastfeed|teen|child|elder|medication|disease|surgery|diabetes|cancer|kidney|liver|hospital|ICU|mortality|life expectancy)\b/i;const calorie=/\b(how many calories|calorie deficit|calories daily|kcal)\b/i;const toolsQ=/\b(app|tool|calculator|online|website)\b/i;const formula=/\b(formula|calculate|calculation|how to|equation|code|python|javascript|excel|google sheets)\b/i;function answerFor(slug,q){if(FORMULA_ANS[slug]&&formula.test(q))return FORMULA_ANS[slug];if(sensitive.test(q))return "There is no single answer for every person. Interpretation depends on age, health status, medications, body composition, and the specific context; medical decisions should use individualized professional guidance.";if(calorie.test(q))return "Calorie requirements vary with body size, activity, body composition, and the goal. Use the relevant FitMe Pro calorie tools as estimates and adjust using longer-term real-world trends.";if(toolsQ.test(q))return "Use the corresponding FitMe Pro calculator with the required inputs and review the method and limitations shown with the result.";return BASE[slug];}const QUESTION_BANK_FAQS=Object.fromEntries(Object.entries(QUESTION_BANK).map(([slug,qs])=>[slug,qs.map(q=>[q,answerFor(slug,q)])]));export{QUESTION_BANK,QUESTION_BANK_FAQS};export default QUESTION_BANK_FAQS;
